import { X } from "lucide-react";
import {
	type PeekItem,
	useNotificationPeek,
} from "@/components/peek/notification-peek-context";
import { PeekPaneContent } from "@/components/peek/peek-pane-content";
import { Button } from "@/components/ui/button";

/**
 * Right-side peek pane. Renders alongside the main content inside the owner
 * layout: when a peek item is open, the layout splits (main shrinks left, this
 * pane shows right). The body mounts the SAME content component the dedicated
 * page uses (see PeekPaneContent) — no duplication. Closes via the X or when
 * the user navigates the main column.
 */
export function NotificationPeekPane() {
	const peek = useNotificationPeek();
	if (!peek?.item) return null;
	return <PeekPaneSurface item={peek.item} onClose={peek.close} />;
}

function PeekPaneSurface({
	item,
	onClose,
}: {
	item: PeekItem;
	onClose: () => void;
}) {
	return (
		<aside className="flex w-[460px] shrink-0 flex-col border-l border-border bg-background">
			<div className="flex h-11 shrink-0 items-center justify-end border-b border-border px-3">
				<Button
					type="button"
					variant="ghost"
					size="icon"
					className="size-7 shrink-0 text-muted-foreground hover:text-foreground"
					aria-label="Close preview"
					onClick={onClose}
				>
					<X className="h-4 w-4" />
				</Button>
			</div>
			<div className="min-h-0 flex-1 overflow-y-auto">
				<PeekPaneContent href={item.href} runId={item.runId} />
			</div>
		</aside>
	);
}

