38	export type ActionApprovalDetails =
39		| FieldChangeApprovalDetails
40		| EntityChangeApprovalDetails;
41	
42	/**
43	 * Escape user/agent-controlled text before it lands in Slack mrkdwn (and the
44	 * in-app Markdown body — both render HTML entities). Without this, a proposed
45	 * field value containing `<!channel>` pings the room from inside a trusted
46	 * approval card, and `<https://evil|Review in Lobu>` spoofs the review link.
47	 */
48	function escapeNotificationText(value: string): string {
49		return value
50			.replace(/&/g, "&amp;")
51			.replace(/</g, "&lt;")
52			.replace(/>/g, "&gt;");
53	}
54	
55	function displayNotificationValue(value: unknown): string {
56		if (value === undefined || value === null || value === "") return "Not set";
57		if (typeof value === "string") return escapeNotificationText(value);
58		return escapeNotificationText(JSON.stringify(value, null, 2));
59	}
60	
61	function truncateNotificationLine(value: string): string {
62		const normalized = value.replace(/\s+/g, " ").trim();
63		return normalized.length > 480
64			? `${normalized.slice(0, 477)}...`
65			: normalized;
66	}
67	
68	/** "$parent_id" → "Parent id", "entity_type" → "Entity type". */
69	export function formatLabel(value: string): string {
70		return value
71			.replace(/^\$/, "")
72			.replace(/[_-]/g, " ")
73			.replace(/\s+/g, " ")
74			.trim()
75			.replace(/^./, (char) => char.toUpperCase());
76	}
