/**
 * Escape user/agent-controlled text for the in-app Markdown body. Neutralises
 * the syntax an attacker could use to forge trusted chrome: `[`/`]`/`(`/`)`
 * (a fake "Review in Lobu" link), and the emphasis/heading/quote marks that
 * would let injected text impersonate the card's own formatting.
 */
function escapeMarkdownText(value: string): string {
	return value.replace(/([\\`*_{}[\]()#+\-!>])/g, "\\$1");
}

input.new_string:
/**
 * Escape user/agent-controlled text for the in-app Markdown body. Narrow by
 * design: only the characters that forge trusted chrome in *inline* context —
 * `[`/`]` (a fake "[Review in Lobu](evil)" link) and the `*`/`_`/`` ` ``
 * emphasis marks that would let injected text impersonate the card's own
 * bolding. Block-level marks (`#`, `>`, `-`) are deliberately NOT escaped:
 * they are inert mid-sentence, and escaping them litters ordinary prose —
 * parentheses, braces and hyphens are common in entity names and JSON values.
 */
function escapeMarkdownText(value: string): string {
	return value.replace(/([\\`*_[\]])/g, "\\$1");
}

