import { Pencil } from "lucide-react";
import { useState } from "react";
import {
	AgentWatcherBehaviorContent,
	type WatcherBehaviorView,
} from "@/components/agents/agent-watchers-route";
import { MemoryEventsPeek } from "@/components/peek/memory-events-peek";
import { parsePeekHref } from "@/components/peek/parse-peek-href";
import { Button } from "@/components/ui/button";
import { WatcherRunThread } from "@/components/watchers/watcher-run-thread";

/**
 * Renders the SAME content component the dedicated page renders, mounted inside
 * the peek pane — never a duplicate. `parsePeekHref` already gated this to
 * previewable destinations (behavior runs, memory events); other activity items
 * (connector detail) navigate to their dedicated page instead of opening the
 * pane, so we always have a known destination here.
 */
export function PeekPaneContent({
	href,
	runId,
}: {
	href: string;
	runId?: number;
}) {
	const dest = parsePeekHref(href);
	if (!dest) return null;

	if (dest.kind === "memory") {
		return <MemoryEventsPeek owner={dest.owner} runId={runId ?? dest.runId} />;
	}

	// Behavior destination — when we have a specific runId, show just that run's
	// transcript, not the full watcher page (tabs, all runs, etc.).
	if (runId) {
		return (
			<WatcherRunThread
				agentId={dest.agentId}
				watcherId={dest.watcherId}
				ownerSlug={dest.owner}
				runId={runId}
			/>
		);
	}
	return (
		<BehaviorPeek
			owner={dest.owner}
			agentId={dest.agentId}
			watcherId={dest.watcherId}
			initialView={dest.view ?? "activity"}
			runId={dest.runId}
		/>
	);
}

/**
 * Behavior content in the peek pane. The Edit toggle is local state (not a router
 * Link) so it flips the pane's surface without navigating the host page.
 */
function BehaviorPeek({
	owner,
	agentId,
	watcherId,
	initialView,
	runId,
}: {
	owner: string;
	agentId: string;
	watcherId: string;
	initialView: WatcherBehaviorView;
	runId?: number;
}) {
	const [view, setView] = useState<WatcherBehaviorView>(initialView);
	const isEditing = view === "definition";
	return (
		<div className="space-y-2">
			<div className="flex justify-end">
				<Button
					type="button"
					variant="ghost"
					size="sm"
					className="h-8 gap-1.5 text-muted-foreground hover:text-foreground"
					onClick={() => setView(isEditing ? "activity" : "definition")}
				>
					{isEditing ? (
						"Done"
					) : (
						<>
							<Pencil className="h-3.5 w-3.5" />
							Edit
						</>
					)}
				</Button>
			</div>
			<AgentWatcherBehaviorContent
				owner={owner}
				agentId={agentId}
				watcherId={watcherId}
				view={view}
				runId={runId}
				onDone={() => setView("activity")}
			/>
		</div>
	);
}

