import { render } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { InlineMarkdownText } from "@/components/markdown-text";
import { notificationSummaryMarkdown } from "@/lib/notification-summary";

/**
 * Renders the timeline card's body node exactly as home-attention-timeline
 * builds it (same summary call, same wrapper classes, same inline renderer),
 * against the five real approval shapes the server emits. Guards the reported
 * bug at the composition level, not just per-unit.
 */
function CardBody({ body }: { body: string }) {
	const summary = notificationSummaryMarkdown(body);
	return summary ? (
		<div className="mt-0.5 line-clamp-2 text-xs text-muted-foreground">
			<InlineMarkdownText text={summary} />
		</div>
	) : null;
}

const CASES: Array<{ name: string; body: string; expected: string }> = [
	{
		name: "person merge (the reported card)",
		body:
			"**An agent** wants to merge [905319918039@s.whatsapp.net](https://app.lobu.ai/buremba/person/member-0faa51dac0).\n" +
			"- Entity id: 886\n- Entity ids: [ 886 ]\n- Winner entity id: 315\n" +
			"\nDuplicate entities need approval before merging.\n" +
			"\n[Review in Lobu](https://app.lobu.ai/buremba/memory?run_ids=42)",
		expected: "An agent wants to merge 905319918039@s.whatsapp.net.",
	},
	{
		name: "field change",
		body:
			"**Watcher <One>** wants to update [App & Crashes](https://app.lobu.ai/acme/topic/app-crashes):\n" +
			"- Severity: ~high~\n→ critical\n" +
			"\nField is protected: severity (currently set by you).\n" +
			"\n[Review in Lobu](https://app.lobu.ai/acme/runs/42)",
		expected: "Watcher <One> wants to update App & Crashes:",
	},
	{
		name: "entity create",
		body:
			"**A watcher** wants to create Slow & Loading.\n" +
			"- Entity type: topic\n- Name: Slow & Loading\n- Parent id: 3\n" +
			'\nA watcher proposes creating topic "Slow & Loading".',
		expected: "A watcher wants to create Slow & Loading.",
	},
	{
		name: "entity delete",
		body:
			"**An agent** wants to delete [Old <Topic>](https://app.lobu.ai/acme/topic/old-topic).\n" +
			"- Entity id: 11\n- Force delete tree: false\n" +
			"\n[Review in Lobu](https://app.lobu.ai/acme/runs/45)",
		expected: "An agent wants to delete Old <Topic>.",
	},
	{
		name: "generic connection action",
		body:
			"A queued action on GitHub is waiting for your review.\n" +
			"\nReview: [Review in Lobu](https://app.lobu.ai/acme/runs/46)",
		expected: "A queued action on GitHub is waiting for your review.",
	},
];

describe("attention timeline card body", () => {
	for (const c of CASES) {
		it(`renders ${c.name} as clean prose`, () => {
			const { container } = render(<CardBody body={c.body} />);
			expect(container.textContent).toBe(c.expected);
			// No markdown syntax may reach the user, and no HTML entity either.
			expect(container.textContent).not.toContain("**");
			expect(container.textContent).not.toContain("](");
			expect(container.textContent).not.toContain("&amp;");
			expect(container.textContent).not.toContain("&lt;");
		});
	}

	it("keeps the entity link clickable in the card", () => {
		const { container } = render(<CardBody body={CASES[0].body} />);
		const link = container.querySelector("a");
		expect(link).toHaveAttribute(
			"href",
			"https://app.lobu.ai/buremba/person/member-0faa51dac0",
		);
	});
});

