42	/**
43	 * Escape user/agent-controlled text before it lands in Slack mrkdwn. Without
44	 * this, a proposed field value containing `<!channel>` pings the room from
45	 * inside a trusted approval card, and `<https://evil|Review in Lobu>` spoofs
46	 * the review link.
47	 *
48	 * Slack-only: the persisted in-app body is Markdown source, not Slack mrkdwn.
49	 * Storing Slack's HTML entities there couples plain-text consumers to Slack
50	 * escaping. The Markdown emitter neutralises its own injection vectors via
51	 * `escapeMarkdownText`.
52	 */
53	function escapeSlackText(value: string): string {
54		return value
55			.replace(/&/g, "&amp;")
56			.replace(/</g, "&lt;")
57			.replace(/>/g, "&gt;");
58	}
59	
60	/**
61	 * Escape user/agent-controlled text for the in-app Markdown body. Narrow by
62	 * design — it must neutralise forged chrome without littering ordinary prose,
63	 * because these strings are entity names and JSON values full of brackets,
64	 * braces and hyphens:
65	 *  - `*`/`_`/`` ` `` — emphasis marks that would let injected text impersonate
66	 *    the card's own bolding.
67	 *  - A closing `]` before `(` or `[` — enough to break inline/reference links,
68	 *    including labels with nested or escaped brackets. A bare `[ 886 ]` is
69	 *    inert in Markdown and stays untouched.
70	 *  - Leading Markdown block marks — reasons render as their own paragraph, so
71	 *    headings, quotes, and lists must remain literal text there.
72	 */
73	function escapeMarkdownText(value: string): string {
74		return value
75			.replace(/([\\`*_])/g, "\\$1")
76			.replace(/\](?=[([])/g, "\\]")
77			.replace(/^([ \t]{0,3})(-{3,}|={3,})(?=\s*$)/gm, "$1\\$2")
78			.replace(/^([ \t]{0,3})(?=[#>+-](?:\s|$))/gm, "$1\\")
79			.replace(/^([ \t]{0,3}\d{1,9})([.)])(?=\s|$)/gm, "$1\\$2");
80	}
