import { fireEvent, render, screen } from "@testing-library/react";
import type { ReactNode } from "react";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { HomeAttentionTimeline } from "./home-attention-timeline";

const { navigate, markRead } = vi.hoisted(() => ({
	navigate: vi.fn(),
	markRead: vi.fn(),
}));

vi.mock("@tanstack/react-router", () => ({
	useNavigate: () => navigate,
	Link: ({ children }: { children: ReactNode }) => children,
}));
vi.mock("@/components/peek/notification-peek-context", () => ({
	useNotificationPeek: () => null,
}));
vi.mock("@/hooks/use-org-context", () => ({
	useOrgContext: () => ({ orgContext: "acme" }),
}));
vi.mock("@/lib/api/activity", () => ({
	useActivityFeed: () => ({
		data: [
			{
				id: "notification-42",
				kind: "notification",
				at: "2026-07-27T12:00:00.000Z",
				title: "Review merging person",
				body:
					"**An agent** wants to merge [Duplicate Person](https://app.lobu.ai/acme/person/duplicate).\n" +
					"- Entity id: 886\n- Winner entity id: 315",
				href: "/acme/memory?run_ids=42",
				notification_id: 42,
				status: "action_approval_needed",
				unread: false,
			},
		],
		isLoading: false,
		isError: false,
	}),
}));
vi.mock("@/lib/api/notifications", () => ({
	useMarkNotificationRead: () => ({ mutate: markRead }),
}));
vi.mock("@/lib/auth-state", () => ({
	useAuthState: () => ({ session: { user: { id: "user-1" } } }),
}));

describe("HomeAttentionTimeline notification summary", () => {
	beforeEach(() => {
		navigate.mockClear();
		markRead.mockClear();
	});

	it("renders only the Markdown summary with a working entity link", () => {
		render(
			<HomeAttentionTimeline owner="acme" filter="all" />,
		);

		expect(screen.getByText("An agent").tagName).toBe("STRONG");
		expect(screen.queryByText(/Entity id/)).toBeNull();
		expect(screen.getByRole("link", { name: "Duplicate Person" })).toHaveAttribute(
			"href",
			"https://app.lobu.ai/acme/person/duplicate",
		);
	});

	it("does not let a nested link keypress activate the timeline row", () => {
		render(
			<HomeAttentionTimeline owner="acme" filter="all" />,
		);

		fireEvent.keyDown(
			screen.getByRole("link", { name: "Duplicate Person" }),
			{ key: "Enter" },
		);

		expect(navigate).not.toHaveBeenCalled();
	});
});

