57	const FILTER_OPTIONS: { value: ActivityFilter; label: string }[] = [
58		{ value: "all", label: "All activity" },
59		{ value: "notifications", label: "Notifications" },
60		{ value: "behavior_runs", label: "Behavior runs" },
61		{ value: "syncs", label: "Feed syncs" },
62	];
