64	/**
65	 * Home activity filter with a notifications-first default: start on
66	 * "notifications", and once that feed loads empty, fall back to "all" — but
67	 * only if the user hasn't already picked a filter. Any manual change sticks.
68	 * Returns [filter, setFilter] like useState; wrap onFilterChange with the
69	 * returned setter so manual selections suppress the auto-fallback.
70	 */
71	export function useNotificationsFirstFilter(): [
72		ActivityFilter,
73		(next: ActivityFilter) => void,
74	] {
75		const { session } = useAuthState();
76		const { orgContext } = useOrgContext();
77		const [filter, setFilter] = useState<ActivityFilter>("notifications");
78		const userPicked = useRef(false);
79	
80		const { data, isSuccess } = useNotifications(session ? orgContext : null);
81		const isEmpty =
82			isSuccess &&
83			(data?.pages.flatMap((p) => p.notifications).length ?? 0) === 0;
84	
85		useEffect(() => {
86			// Auto-fallback to "all" only on the initial empty-notifications load,
87			// and never after the user has made an explicit choice.
88			if (isEmpty && !userPicked.current && filter === "notifications") {
89				setFilter("all");
90			}
91		}, [isEmpty, filter]);
92	
93		const setFilterFromUser = (next: ActivityFilter) => {
94			userPicked.current = true;
95			setFilter(next);
96		};
97	
98		return [filter, setFilterFromUser];
99	}
