	const text = summary.join(" ").trim();
	if (text !== "") return text;

	// No leading prose. Approval bodies always have some, but an agent digest can
	// open straight into a bullet list — returning null there would blank the card
	// body entirely, which is worse than the untruncated text it used to show.
	// Fall back to the leading lines (minus the review CTA); the card clamps them.
	const fallback = body
		.split("\n")
		.map((line) => line.trim())
		.filter((line) => line !== "" && !REVIEW_LINK_LINE.test(line))
		.join(" ")
		.trim();
	return fallback === "" ? null : fallback;
}

