import { describe, expect, it } from "vitest";
import { notificationSummaryMarkdown } from "./notification-summary";

/**
 * Inputs mirror the server outputs pinned in
 * packages/server/src/__tests__/unit/approval-notification-render.test.ts so
 * this stays honest about the shape the timeline receives.
 */
describe("notificationSummaryMarkdown", () => {
	it("keeps the summary sentence and drops the detail list", () => {
		const body =
			"**An agent** wants to merge [905319918039@s.whatsapp.net](https://app.lobu.ai/buremba/person/member-0faa51dac0).\n" +
			"- Entity id: 886\n- Entity ids: [ 886 ]\n- Winner entity id: 315";
		expect(notificationSummaryMarkdown(body)).toBe(
			"**An agent** wants to merge [905319918039@s.whatsapp.net](https://app.lobu.ai/buremba/person/member-0faa51dac0).",
		);
	});

	it("drops the diff list from a field-change body", () => {
		const body =
			"**Watcher <One>** wants to update [App & Crashes](https://app.lobu.ai/acme/topic/app-crashes):\n" +
			"- Severity: ~high~\n→ critical\n" +
			"\nField is protected: severity (currently set by you).\n" +
			"\n[Review in Lobu](https://app.lobu.ai/acme/runs/42)";
		expect(notificationSummaryMarkdown(body)).toBe(
			"**Watcher <One>** wants to update [App & Crashes](https://app.lobu.ai/acme/topic/app-crashes):",
		);
	});

	it("drops the reason paragraph and the review link", () => {
		const body =
			"**A watcher** wants to create Slow & Loading.\n" +
			"- Entity type: topic\n" +
			'\nA watcher proposes creating topic "Slow & Loading".\n' +
			"\n[Review in Lobu](https://app.lobu.ai/acme/runs/44)";
		expect(notificationSummaryMarkdown(body)).toBe(
			"**A watcher** wants to create Slow & Loading.",
		);
	});

	it("keeps a plain generic body that has no detail lines", () => {
		expect(
			notificationSummaryMarkdown(
				"A queued action on GitHub is waiting for your review.\n" +
					"\nReview: [Review in Lobu](https://app.lobu.ai/acme/runs/46)",
			),
		).toBe("A queued action on GitHub is waiting for your review.");
	});

	it("rejoins a summary sentence that wraps across lines", () => {
		expect(
			notificationSummaryMarkdown("**An agent** wants to merge\nDuplicate Person (#12)."),
		).toBe("**An agent** wants to merge Duplicate Person (#12).");
	});

	it("skips leading blank lines before the summary", () => {
		expect(notificationSummaryMarkdown("\n\n**A watcher** wants to merge X.")).toBe(
			"**A watcher** wants to merge X.",
		);
	});

	it("returns null when there is no renderable prose", () => {
		expect(notificationSummaryMarkdown(null)).toBeNull();
		expect(notificationSummaryMarkdown(undefined)).toBeNull();
		expect(notificationSummaryMarkdown("")).toBeNull();
		expect(notificationSummaryMarkdown("   \n  ")).toBeNull();
		expect(notificationSummaryMarkdown("- Entity id: 886")).toBeNull();
		expect(
			notificationSummaryMarkdown("[Review in Lobu](https://app.lobu.ai/acme/runs/42)"),
		).toBeNull();
	});
});

