/**
 * Same inline renderer, links defanged: the label still shows, but no anchor is
 * emitted. For bodies whose author is not the product itself — an agent calling
 * `notifications.send({ body })` supplies that string verbatim, so a live
 * `[do not click](https://evil)` inside trusted-looking chrome is phishing.
 */
const inlineComponentsNoLinks: Components = {
	...inlineComponents,
	a: ({ children }) => <>{children}</>,
};

/** Same-origin app link (relative, or absolute onto this deployment's host). */
function isOwnAppHref(href: string | undefined): boolean {
	if (!href) return false;
	try {
		const base =
			typeof window === "undefined" ? "https://localhost" : window.location.href;
		const url = new URL(href, base);
		if (url.protocol !== "https:" && url.protocol !== "http:") return false;
		return typeof window === "undefined" || url.host === window.location.host;
	} catch {
		return false;
	}
}

/**
 * Links are rendered as anchors only when the href points back at this app.
 *
 * Trusting by notification *type* is not enough: the generic approval branch
 * interpolates a connection name, and rows written before the body escaping
 * existed are still in `events` and can never be re-escaped. Validating the
 * resolved href covers both, and still lets our own `[Name](/org/person/x)`
 * entity permalinks stay clickable.
 */
const inlineComponentsOwnLinksOnly: Components = {
	...inlineComponents,
	a: ({ href, children }) =>
		isOwnAppHref(href) ? (
			<a
				href={href}
				target="_blank"
				rel="noopener noreferrer"
				className="font-medium text-primary underline underline-offset-2"
			>
				{children}
			</a>
		) : (
			<>{children}</>
		),
};

export const InlineMarkdownText: FC<{
	text: string;
	className?: string;
	/**
	 * "app-links" keeps anchors whose href resolves to this app and strips every
	 * external one — for server-composed bodies (approvals). "strip" is the
	 * default and emits no anchors at all: safe for arbitrary agent-authored text.
	 */
	linkPolicy?: "app-links" | "strip";
}> = ({ text, className, linkPolicy = "strip" }) => {
	return (
		<span className={cn("break-words", className)}>
			<ReactMarkdown
				remarkPlugins={[remarkGfm]}
				components={
					linkPolicy === "app-links"
						? inlineComponentsOwnLinksOnly
						: inlineComponentsNoLinks
				}
			>
				{text}
			</ReactMarkdown>
		</span>
	);
};

