import { render } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { MarkdownText } from "./markdown-text";

/**
 * `MarkdownText` renders model-authored prose — chat replies (agent-thread),
 * event cards, and JSON-renderer text nodes. Markup that reaches out to another
 * host is an injection vector there, not formatting.
 */
describe("MarkdownText outbound markup", () => {
	it("renders an embedded image as alt text, never an <img>", () => {
		const { container } = render(
			<MarkdownText text="Here is the chart ![pixel](https://evil.example/track)" />,
		);
		expect(container.querySelector("img")).toBeNull();
		expect(container.textContent).toBe("Here is the chart pixel");
	});

	it("drops external links to plain text", () => {
		const { container } = render(
			<MarkdownText text="Click [here](https://evil.example) now" />,
		);
		expect(container.querySelector("a")).toBeNull();
		expect(container.textContent).toBe("Click here now");
	});

	it("drops non-http schemes", () => {
		const { container } = render(
			<MarkdownText text="[click](javascript:alert(1))" />,
		);
		expect(container.querySelector("a")).toBeNull();
	});

	it("keeps same-origin app links clickable", () => {
		const { container } = render(
			<MarkdownText text="See [the person](/acme/person/dup)" />,
		);
		expect(container.querySelector("a")).toHaveAttribute(
			"href",
			"/acme/person/dup",
		);
	});

	it("still renders ordinary prose formatting", () => {
		// The hardening must not cost the styling this component exists for.
		const { container } = render(
			<MarkdownText text={"# Heading\n\n**bold** and `code`\n\n- one\n- two"} />,
		);
		expect(container.querySelector("h1")?.textContent).toBe("Heading");
		expect(container.querySelector("strong")?.textContent).toBe("bold");
		expect(container.querySelector("code")?.textContent).toBe("code");
		expect(container.querySelectorAll("li")).toHaveLength(2);
	});
});

