    strongCount: clamp?.querySelectorAll('strong').length ?? 0,
    links: [...(clamp?.querySelectorAll('a')||[])].map(a=>a.getAttribute('href')),
    imgs: clamp?.querySelectorAll('img').length ?? 0
  };
});
JSON.stringify({approvalRows: rows.length, cards: out}, null, 1)

