import type React from 'react';
import { z } from 'zod';
import type { ValueFormat } from './format-value';

// Define the node types first
export type TextNode = {
  type: 'text';
  content: string;
};

export type DataBinding = {
  type: 'data';
  path: string;
  fallback?: unknown;
  /**
   * Optional display-format directive applied to the bound scalar (currency,
   * date, url, enum, boolean, number). Resolved from a field's JSON-Schema
   * annotation by whoever authors the template; the renderer only formats. When
   * omitted, values auto-format by shape (dates/urls), never as currency.
   */
  format?: ValueFormat;
};

export type ComponentType =
  | 'card'
  | 'card-header'
  | 'card-title'
  | 'card-description'
  | 'card-content'
  | 'badge'
  | 'button'
  | 'alert'
  | 'alert-title'
  | 'alert-description'
  | 'progress'
  | 'separator'
  | 'markdown'
  | 'div'
  | 'span'
  | 'p'
  | 'h1'
  | 'h2'
  | 'h3'
  | 'h4'
  | 'ul'
  | 'ol'
  | 'li'
  | 'table'
  | 'thead'
  | 'tbody'
  | 'tr'
  | 'th'
  | 'td';

export type ComponentNode = {
  // A base ComponentType, or any app-registered component name (resolved from
  // RenderContext.components at render time). The `string & {}` keeps editor
  // autocomplete for the known types while allowing app component node types
  // (e.g. 'entity-board', 'entity-link') the generic renderer knows nothing of.
  type: ComponentType | (string & {});
  props?: Record<string, unknown>;
  children?: JsonNode[];
};

export type ConditionalNode = {
  type: 'if';
  condition: string;
  then: JsonNode;
  else?: JsonNode;
};

export type LoopNode = {
  type: 'each';
  items: string;
  as: string;
  render: JsonNode | string; // String shorthand: "- {{var}}" interpolated per item
};

export type JsonNode = TextNode | ComponentNode | DataBinding | ConditionalNode | LoopNode;

export type JsonTemplate = {
  version: 1;
  root: JsonNode;
};

