/**
 * SPIKE: can a notification be expressed as a json_template whose action
 * buttons dispatch real mutations? Proves the renderer half of the contract.
 * The server-validator half is proven in the server suite.
 */

import { fireEvent, render, screen } from '@testing-library/react';
import { describe, expect, it, vi } from 'vitest';
import { JsonRenderer } from './renderer';
import type { JsonNode } from './types';

/** Shape a notification emitter would store instead of a markdown body. */
const APPROVAL_TEMPLATE = {
  type: 'div',
  children: [
    {
      type: 'markdown',
      props: { content: '**An agent** wants to merge {{entityName}}.' },
    },
    {
      type: 'div',
      children: [
        {
          type: 'button',
          props: { onClick: '@approve', variant: 'default' },
          children: [{ type: 'text', content: 'Approve' }],
        },
        {
          type: 'button',
          props: { onClick: '@reject', variant: 'outline' },
          children: [{ type: 'text', content: 'Reject' }],
        },
      ],
    },
  ],
} as unknown as JsonNode;

describe('notification json_template', () => {
  it('renders body + action buttons and dispatches the bound mutations', () => {
    const approve = vi.fn();
    const reject = vi.fn();
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {});

    render(
      <JsonRenderer
        template={{ root: APPROVAL_TEMPLATE }}
        data={{ entityName: '905319918039@s.whatsapp.net' }}
        actions={{ approve, reject }}
      />
    );

    // Body data-binding resolved
    expect(screen.getByText(/905319918039@s\.whatsapp\.net/)).toBeTruthy();

    fireEvent.click(screen.getByText('Approve'));
    expect(approve).toHaveBeenCalledTimes(1);
    expect(reject).not.toHaveBeenCalled();

    fireEvent.click(screen.getByText('Reject'));
    expect(reject).toHaveBeenCalledTimes(1);

    // No malformed-handler warnings on a well-formed template
    expect(warn).not.toHaveBeenCalled();
    warn.mockRestore();
  });

  it('does not invoke an action the host did not register', () => {
    const approve = vi.fn();
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {});

    // An agent-authored template naming a mutation the host never provided.
    render(
      <JsonRenderer
        template={{
          root: {
            type: 'button',
            props: { onClick: '@deleteEverything' },
            children: [{ type: 'text', content: 'Danger' }],
          } as unknown as JsonNode,
        }}
        data={{}}
        actions={{ approve }}
      />
    );

    fireEvent.click(screen.getByText('Danger'));
    expect(approve).not.toHaveBeenCalled();
    // Unresolved handler is dropped, with a warning — no crash.
    expect(warn).toHaveBeenCalled();
    warn.mockRestore();
  });
});

