input.new_string:
	/** entity_change action sentence ("Create/Delete this entity"). */
	action: string | null;
	proposal: Array<{ label: string; value: string }>;
	/** Fully formatted "why" text; null omits the section. */
	why: string | null;
}

/**
 * What the recipient can DO about an approval, declared once and projected to
 * every surface (chat card buttons, in-app feed buttons, the peek link).
 *
 * WHY a declaration rather than per-surface construction: the chat card used to
 * build its buttons straight from `runId` while the in-app feed re-derived the
 * run from notification metadata — which stores `resource_type: "event"`, so the
 * lookup failed and the web silently rendered a link-only card. A single
 * declaration means a surface can only fail to render actions, never fail to
 * know about them.
 *
 * `runId` rides the mutation actions so no consumer parses it back out of a
 * permalink; `link` carries an absolute-or-relative URL the surface renders
 * natively (Slack/Telegram link button, in-app anchor).
 */
export type ApprovalAction =
	| {
			kind: "approve_run" | "reject_run";
			label: string;
			style: "primary" | "danger";
			runId: number;
	  }
	| { kind: "link"; label: string; url: string };

/**
 * Declare the actions for an approval notification.
 *
 * Structured approvals (entity create/delete/merge and field changes) are the
 * only kinds with a safe one-click semantic, so they are the only ones that get
 * the mutations — an unstructured `actionKey` approval gets nothing here and
 * falls back to its body text. A missing `runId` degrades to the review link
 * alone rather than rendering a button that cannot resolve a target.
 */
export function buildApprovalActions(params: {
	runId?: number;
	approvalUrl?: string;
	details?: ActionApprovalDetails;
}): ApprovalAction[] {
	if (
		!params.details ||
		!["entity_field_change", "entity_change"].includes(params.details.kind)
	) {
		return [];
	}
	const actions: ApprovalAction[] = [];
	if (params.runId) {
		actions.push({
			kind: "approve_run",
			label: "Approve",
			style: "primary",
			runId: params.runId,
		});
		actions.push({
			kind: "reject_run",
			label: "Reject",
			style: "danger",
			runId: params.runId,
		});
	}
	if (params.approvalUrl) {
		actions.push({
			kind: "link",
			label: "Review in Lobu",
			url: params.approvalUrl,
		});
	}
	return actions;
}

