 * permalink; `link` carries an absolute-or-relative URL the surface renders
 * natively (Slack/Telegram link button, in-app anchor).
 */
export type ApprovalAction =
	| {
			kind: "approve_run" | "reject_run";
			label: string;
			style: "primary" | "danger";
			runId: number;
	  }
	| { kind: "link"; label: string; url: string };

/**
 * Declare the actions for an approval notification.
 *
 * Structured approvals (entity create/delete/merge and field changes) are the
 * only kinds with a safe one-click semantic, so they are the only ones that get
 * the mutations — an unstructured `actionKey` approval gets nothing here and
 * falls back to its body text. A missing `runId` degrades to the review link
 * alone rather than rendering a button that cannot resolve a target.
 */
export function buildApprovalActions(params: {
	runId?: number;
	approvalUrl?: string;
	details?: ActionApprovalDetails;
}): ApprovalAction[] {
	if (
		!params.details ||
		!["entity_field_change", "entity_change"].includes(params.details.kind)
	) {
		return [];
	}
	const actions: ApprovalAction[] = [];
	if (params.runId) {
		actions.push({
			kind: "approve_run",
			label: "Approve",
			style: "primary",
			runId: params.runId,
		});
		actions.push({
			kind: "reject_run",
			label: "Reject",
			style: "danger",
			runId: params.runId,
		});
	}
	if (params.approvalUrl) {
		actions.push({
			kind: "link",
			label: "Review in Lobu",
			url: params.approvalUrl,
		});
	}
	return actions;
}

