	useMarkNotificationRead: () => ({ mutate: markRead }),
}));
vi.mock("@/lib/auth-state", () => ({
	useAuthState: () => ({ session: { user: { id: "user-1" } } }),
}));

describe("HomeAttentionTimeline notification summary", () => {
	beforeEach(() => {
		navigate.mockClear();
		markRead.mockClear();
	});

	it("renders only the Markdown summary with a working entity link", () => {
		render(
			<HomeAttentionTimeline owner="acme" filter="all" />,
		);

		expect(screen.getByText("An agent").tagName).toBe("STRONG");
		expect(screen.queryByText(/Entity id/)).toBeNull();
		expect(screen.getByText(/raw provider detail/)).toBeInTheDocument();
		expect(screen.getByRole("link", { name: "Duplicate Person" })).toHaveAttribute(
			"href",
			"/acme/person/duplicate",
		);
	});

	it("does not let a nested link keypress activate the timeline row", () => {
		render(
			<HomeAttentionTimeline owner="acme" filter="all" />,
		);

		fireEvent.keyDown(
			screen.getByRole("link", { name: "Duplicate Person" }),
			{ key: "Enter" },
		);

		expect(navigate).not.toHaveBeenCalled();
	});
});

