import { useLocation, useNavigate, useParams } from "@tanstack/react-router";
import {
	createContext,
	type ReactNode,
	useCallback,
	useContext,
	useEffect,
	useMemo,
	useState,
} from "react";
import { parsePeekHref } from "@/components/peek/parse-peek-href";
import {
	destinationHrefFromPeekSearch,
	hasPeekFlag,
	mergePeekSearch,
	omitPeekSearch,
	peekSearchFromDestinationHref,
	pickPeekSearch,
} from "@/lib/peek-search";

/**
 * A clicked activity/notification item that should open in the right-side peek
 * pane (instead of navigating to its dedicated page). The pane reuses the SAME
 * content component the dedicated page renders — never a duplicate.
 *
 * Peek target is sticky in the URL (`?peek=1&peek_run_id=…` etc.) so reloads,
 * sidepanel deep-links, and "click → query param" all share one path.
 */
export interface PeekItem {
	/** App-relative href of the destination (same string a plain click navigates to). */
	href: string;
	/** Title for the pane header. */
	title: string;
	/** The specific run this item represents (shows just that run, not the whole watcher). */
	runId?: number;
}

interface NotificationPeekValue {
	item: PeekItem | null;
	open: (item: PeekItem) => void;
	close: () => void;
}

const NotificationPeekContext = createContext<NotificationPeekValue | null>(
	null,
);

function titleForPeekHref(href: string, fallback?: string): string {
	if (fallback?.trim()) return fallback.trim();
	const dest = parsePeekHref(href);
	if (!dest) return "Details";
	if (dest.kind === "memory" && dest.runId != null) {
		return `Run #${dest.runId}`;
	}
	if (dest.kind === "behavior") {
		return dest.runId != null ? `Behavior run #${dest.runId}` : "Behavior";
	}
	return "Details";
}

