import { useMemo } from "react";
import { EventCard } from "@/components/entity-tabs/events-tab/event-card";
import { collapseSupersedeChains } from "@/components/entity-tabs/events-tab/navigation";
import { Spinner } from "@/components/ui/spinner";
import { useWorkspaceRoot } from "@/lib/api";
import { useInfiniteContentWithFilters } from "@/lib/api/content";

/**
 * Inline Memory events preview for the peek pane. Reuses the SAME data query
 * (`useInfiniteContentWithFilters`) and the SAME card (`EventCard`) that the
 * Memory page's EventsTab renders — never a duplicate. Scoped to a single run
 * so an approval notification shows exactly its proposal card (with the real
 * Approve / Reject form when the event carries approval interaction data).
 */
export function MemoryEventsPeek({
	owner,
	runId,
}: {
	owner: string;
	runId?: number;
}) {
	const { data: workspaceData, isLoading: workspaceLoading } = useWorkspaceRoot(
		owner,
		{ slug: owner },
	);
	// ResolvedNamespace.id is the org UUID when type === "organization"
	// (see OwnerWorkspaceGate, which derives organizationId the same way).
	const workspace = workspaceData?.workspace;
	const organizationId =
		workspace?.type === "organization" ? workspace.id : null;

	// Memory peek is always scoped to one run. Without a runId the query
	// stays disabled (we render an empty state below) — never fetch all events.
	const filters = useMemo(
		() => (runId != null ? { runIds: [runId] } : undefined),
		[runId],
	);

	const query = useInfiniteContentWithFilters(
		organizationId,
		undefined,
		filters,
		owner,
	);

	const contents = useMemo(
		() =>
			collapseSupersedeChains(
				(query.data?.pages ?? []).flatMap((p) => p.content),
			),
		[query.data],
	);

	if (workspaceLoading) {
		return (
			<div className="flex items-center justify-center py-12 text-muted-foreground">
				<Spinner className="mr-2" /> Loading…
			</div>
		);
	}

	// Workspace resolved but org is null (not an organization, or no access).
	// Show an error instead of spinning forever.
	if (organizationId == null) {
		return (
			<div className="px-4 py-8 text-center text-sm text-muted-foreground">
				Couldn't resolve this workspace.
			</div>
		);
	}

	if (runId == null) {
		return (
			<div className="px-4 py-8 text-center text-sm text-muted-foreground">
				Nothing to preview.
			</div>
		);
	}

	if (query.isLoading && contents.length === 0) {
		return (
			<div className="flex items-center justify-center py-12 text-muted-foreground">
				<Spinner className="mr-2" /> Loading…
			</div>
		);
	}

	if (query.error) {
		return (
			<div className="px-4 py-8 text-center text-sm text-muted-foreground">
				Couldn't load this event.
			</div>
		);
	}

	if (contents.length === 0) {
		return (
			<div className="px-4 py-8 text-center text-sm text-muted-foreground">
				No events for this run yet.
			</div>

