/**
 * Ephemeral: create a REAL entity-merge approval through the production code
 * path (proposeEntityMerge → run + pending approval event + notification), so
 * the browser can drive approve end-to-end. Hand-written runs rows miss the
 * proposal event and the action_input shape the executor requires.
 */
import { proposeEntityMerge } from "./src/tools/admin/entity-field-approval";
import type { ToolContext } from "./src/tools/registry";

const organizationId = process.env.SEED_ORG_ID;
const userId = process.env.SEED_USER_ID;
const winner = Number(process.env.SEED_WINNER_ID);
const loser = Number(process.env.SEED_LOSER_ID);
if (!organizationId || !userId || !Number.isFinite(winner) || !Number.isFinite(loser)) {
	throw new Error("SEED_ORG_ID, SEED_USER_ID, SEED_WINNER_ID, SEED_LOSER_ID required");
}

const ctx = {
	organizationId,
	userId,
	memberRole: "owner",
} as ToolContext;

const result = await proposeEntityMerge(ctx, {
	entity_ids: [loser],
	winner_entity_id: winner,
	reason: "No configured deterministic identity rule proves this merge.",
});

console.log(JSON.stringify(result, null, 2));
process.exit(0);

