49	/**
50	 * Forward a notification to the org's active chat-bot connections so it lands
51	 * in the bound channel — e.g. a watcher digest posting to #leads.
52	 *
53	 * Resolves connections + their Behavior subscriptions straight from Postgres and
54	 * posts in-process via the chat manager. Every app pod loads every active
55	 * connection at boot, so the locally-held instance can post regardless of
56	 * which pod fired the notification — correct under N>1 replicas, no cross-pod
57	 * routing needed.
58	 *
59	 * Best-effort: a connection with no live instance or no binding is skipped
60	 * without failing the others. A connection bound to several channels posts to
61	 * each.
62	 */
63	interface BotDeliveryTarget {
64		connectionId: string;
65		platform: string;
66		/** Platform-prefixed channel id ready for `chat.channel()`, e.g. "slack:C0123ABCD". */
67		channelKey: string;
