69		teamId: string | null;
70	}
71	
72	/**
73	 * Resolve where a notification should be posted.
74	 *
75	 * Two branches, UNIONed:
76	 *
77	 *   (A) The org's OWN active chat connections JOINed to their subscriptions,
78	 *       scoped to (org, agent) — the multi-tenant default. A connection with no
79	 *       subscription has no target; several subscribed channels yield one
80	 *       target each.
81	 *
82	 *   (B) Hosted-preview cross-org delivery. The hosted preview bot is ONE
83	 *       connection living in its OWN org under a placeholder agent, that fans
84	 *       out to agents across MANY orgs — a `/lobu link <code>` writes the
85	 *       subscription under the claim's org, never the connection's. So branch (A)'s
86	 *       `(org, agent)` JOIN misses it on BOTH columns and proactive
87	 *       notifications silently drop. This branch resolves the org's bindings
88	 *       through the shared preview connection, mirroring the inbound
89	 *       concrete-connection routing. It is gated HARD to previewMode
90	 *       connections with no `metadata.teamId` (the hosted-bot invariant, same as
91	 *       `getDefaultConnection`) and is NOT joined on `agent_id`, so a normal
92	 *       tenant bot can never be used to deliver cross-org.
93	 *
94	 * Single-workspace assumption: with exactly one hosted preview connection per
95	 * platform today, (B) matches on platform alone. When a second hosted workspace
96	 * appears, persist its Slack team id (e.g. `settings.hostedWorkspaceTeamId`) and
97	 * add `AND ac.settings->>'hostedWorkspaceTeamId' = b.team_id` so a subscription only
98	 * resolves the connection actually installed in its workspace (Slack channel ids
99	 * are workspace-scoped, not global).
100	 *
101	 * Exported for testing the delivery path against a real DB.
102	 */
103	export async function resolveBotDeliveryTargets(
104		organizationId: string,
105		opts?:
106			| string
107			| null
108			| {
109					connectionId?: string | null;
110					channelId?: string | null;
111					teamId?: string | null;
112			  },
113	): Promise<BotDeliveryTarget[]> {
114		const connectionId =
115			typeof opts === "string" || opts === null ? opts : opts?.connectionId;
116		const channelId =
