118		const teamId = typeof opts === "object" && opts !== null ? opts.teamId : null;
119		// Org-wide (no agentId): every channel any of the org's agents is bound to,
120		// resolved through the right connection. Shared resolver = one home for the
121		// cross-org preview invariant (see bound-channels.ts).
122		const rows = await resolveBoundChannelRows(getDb(), {
123			organizationId,
124			connectionId,
125		});
126	
127		const normalizedChannelId = channelId
128			? channelId.includes(":")
129				? channelId
130				: null
