42	/**
43	 * Escape user/agent-controlled text before it lands in Slack mrkdwn. Without
44	 * this, a proposed field value containing `<!channel>` pings the room from
45	 * inside a trusted approval card, and `<https://evil|Review in Lobu>` spoofs
46	 * the review link.
47	 *
48	 * Slack-only: the persisted in-app body is Markdown source, not Slack mrkdwn.
49	 * Storing Slack's HTML entities there couples plain-text consumers to Slack
50	 * escaping. The Markdown emitter neutralises its own injection vectors via
51	 * `escapeMarkdownText`.
52	 */
53	function escapeSlackText(value: string): string {
54		return value
55			.replace(/&/g, "&amp;")
56			.replace(/</g, "&lt;")
57			.replace(/>/g, "&gt;");
58	}
