60	/**
61	 * Escape user/agent-controlled text for the in-app Markdown body (GFM, so
62	 * strikethrough and autolinks are live too). These strings are entity names,
63	 * actor labels, and JSON values, and they get interpolated INTO our own
64	 * `**bold**` and `[label](url)` chrome — so anything that could terminate that
65	 * chrome early, or start markup of its own, has to be neutralised:
66	 *  - `` \ ` * _ ~ `` — emphasis/strikethrough/code delimiters. Missing `~` let
67	 *    an actor named `~~trusted agent~~` render struck-through.
68	 *  - `[` and `]` — a stray `]` closes our link label early, letting the rest of
69	 *    the name escape the anchor. Escaping is unconditional: a lookahead rule
70	 *    (only before `(`) missed unmatched brackets. The renderer strips the
71	 *    backslashes, so `[ 886 ]` still displays literally.
72	 *  - `<` and `>` — GFM autolinks. `<https://evil.example>` became a real
73	 *    attacker-controlled anchor inside a trusted-looking card.
74	 *  - Leading block marks — reasons render as their own paragraph, so headings,
75	 *    quotes, lists, and setext underlines must stay literal text there.
76	 */
77	function escapeMarkdownText(value: string): string {
78		return value
79			.replace(/([\\`*_~[\]<>])/g, "\\$1")
80			// Setext underlines and thematic breaks: ANY run length turns the line
81			// above into a heading ("Trusted line\n=" renders as <h1>), so this is not
82			// limited to the 3+ runs that form a `---` rule.
83			.replace(/^([ \t]{0,3})([-=]+)(?=[ \t]*$)/gm, "$1\\$2")
84			.replace(/^([ \t]{0,3})(?=[#>+-](?:\s|$))/gm, "$1\\")
85			.replace(/^([ \t]{0,3}\d{1,9})([.)])(?=\s|$)/gm, "$1\\$2");
86	}
