205	export function collapseAdjacentActivityCards(items: RawCard[]): RawCard[] {
206		if (items.length <= 1) return items;
207		const out: RawCard[] = [];
208		let i = 0;
209		while (i < items.length) {
210			const head = items[i]!;
211			if (
212				head.kind === "notification" ||
213				!head.collapseKey ||
214				!head.status ||
215				isFailedStatus(head.status)
216			) {
217				out.push(head);
218				i += 1;
219				continue;
220			}
221			let j = i + 1;
222			let itemsSum =
223				typeof head.itemsCollected === "number" ? head.itemsCollected : null;
224			const memberIds = head.run_id != null ? [head.run_id] : [];
225			while (j < items.length) {
226				const next = items[j]!;
227				if (
228					next.kind === "notification" ||
229					next.collapseKey !== head.collapseKey ||
230					next.status !== head.status ||
231					isFailedStatus(next.status)
232				) {
233					break;
234				}
235				if (typeof next.itemsCollected === "number") {
236					itemsSum = (itemsSum ?? 0) + next.itemsCollected;
237				} else if (itemsSum != null) {
238					itemsSum = null;
239				}
240				if (next.run_id != null) memberIds.push(next.run_id);
241				j += 1;
242			}
243			const count = j - i;
244			if (count === 1) {
245				out.push(head);
246			} else {
247				const latest = items[j - 1]!;
248				const status = latest.status ?? "run";
249				const body =
250					itemsSum != null
251						? `${count}× ${status} · ${itemsSum} items total`
252						: `${count}× ${status}`;
253				out.push({
254					...latest,
255					id: `group:${head.collapseKey}:${latest.id}`,
256					kind:
257						latest.kind === "sync"
258							? "sync_group"
259							: latest.kind === "behavior_run"
260								? "behavior_run_group"
261								: `${latest.kind}_group`,
262					body,
263					count,
264					member_run_ids: memberIds,
265				});
266			}
267			i = j;
268		}
269		return out;
270	}
